// Generated by scripts/build-guide.mjs from guide/*.md — do not edit by hand.
export const GUIDE_SOURCES = {
  workflow: "# Workflow\n\n**You write all of the app's code.** The platform provides no templates, starter code or generated code. A new app's repository contains only two platform-managed files — `.github/workflows/deploy.yml` and `platform.json` — which you must never edit. Every other file is yours to create, following the `contract` topic exactly.\n\n## 1. Log in\nCall `whoami`. If it says you're not authenticated, ask the user for their email address, call `request_login_code`, ask the user for the 6-digit code from their inbox, and call `verify_login_code`. The same flow signs new users up.\n\n## 2. Create or pick an app\n- New app: `create_app({ name })`, optionally with a `slug` (the subdomain). The app lives at `https://<slug>.{{APPS_DOMAIN}}`.\n- Existing app: `list_apps`, then `get_app({ app })`.\n- In a new conversation, restore context with `list_files` and `read_file` before changing anything.\n\n## 3. Write the code\n- Follow the `contract` topic exactly (files, `wrangler.jsonc`, `vite.config.ts`, dependencies).\n- `write_files` commits many files at once: up to {{MAX_FILES_PER_WRITE}} files and {{bytes:MAX_WRITE_BYTES}} per call, {{bytes:MAX_FILE_BYTES}} per file.\n- Every commit with `deploy: true` (the default) is built and deployed. For large apps, write in batches with `deploy: false` and set `deploy: true` only on the last batch.\n- Never commit build output, `node_modules/`, lockfiles other than `package-lock.json`, or secrets.\n\n## 4. Follow the deployment\nCall `get_deployment({ app, wait_seconds: 25 })` repeatedly until `status` is `live` or `failed`.\n- `failed` with `CONTRACT_VIOLATION`: fix every item in `error.violations` (each has a `fix`), then write again.\n- `failed` with `BUILD_FAILED`: read `error.errors` (file, line, message) and `error.build_log_excerpt`, fix, write again.\n- `failed` with `MIGRATION_FAILED`: see the `database` topic.\n\n## 5. Verify and hand over\nWhen `live`, give the user the URL. Use `get_logs` to see requests, console output and exceptions, and `query_database` to inspect data.\n\n## 6. Undo\n`rollback({ app, deployment })` re-ships a previous live version (database migrations are not reverted). The next `write_files` with `deploy: true` ships the current code again.\n",
  contract: "# App contract (version {{CONTRACT_VERSION}})\n\nOne Cloudflare Worker serves both a **Hono** API under `/api/*` and a **React** single-page app (built with **Vite**) as static assets. Data lives in a **D1** (SQLite) database, optionally through **Drizzle**. There is no other runtime: no Node server, no SSR framework, no filesystem.\n\n## Required files\n\n```\npackage.json\nwrangler.jsonc\nvite.config.ts\ntsconfig.json\nindex.html\nsrc/api/index.ts      # default-exports the Hono app; API routes under /api/\nsrc/api/env.ts        # the Env interface (bindings, vars, secrets)\nsrc/web/main.tsx      # React entry: createRoot(document.getElementById('root')!).render(<App />)\nmigrations/           # optional: NNNN_description.sql files (see the database topic)\n```\n\nPlatform-managed (never edit): `platform.json`, `.github/workflows/deploy.yml`.\n\n## `wrangler.jsonc` — write exactly this\n\n```jsonc\n// wrangler.jsonc — the platform overrides name, database_name and database_id at deploy time\n{\n  \"$schema\": \"node_modules/wrangler/config-schema.json\",\n  \"name\": \"app\",\n  \"main\": \"src/api/index.ts\",\n  \"compatibility_date\": \"{{COMPATIBILITY_DATE_MAX}}\",\n  \"compatibility_flags\": [\"nodejs_compat\"],\n  \"assets\": {\n    \"not_found_handling\": \"single-page-application\",\n    \"run_worker_first\": [\"/api/*\"]\n  },\n  \"d1_databases\": [\n    { \"binding\": \"DB\", \"database_name\": \"app\", \"database_id\": \"local\", \"migrations_dir\": \"migrations\" }\n  ]\n}\n```\n\nYou may add a `\"vars\"` object with **string** values. Nothing else: no other bindings, `routes`, `triggers`, `env`, `durable_objects`, `services` or `limits`.\n\n## `vite.config.ts` — write exactly this\n\n```ts\nimport { defineConfig } from 'vite';\nimport react from '@vitejs/plugin-react';\nimport { cloudflare } from '@cloudflare/vite-plugin';\n\nexport default defineConfig({ plugins: [react(), cloudflare()] });\n```\n\n## `package.json`\n- `\"type\": \"module\"`, `\"private\": true`, and `\"scripts\": { \"build\": \"vite build\" }`. An optional `\"typecheck\": \"tsc --noEmit\"` script runs during the build.\n- npm only: commit `package-lock.json` or no lockfile at all.\n- Required dependencies (at least these versions):\n\n{{REQUIRED_DEPENDENCIES}}\n\n- `drizzle-orm` is the only supported ORM (optional).\n\n## `index.html`\nAt the repo root, with `<div id=\"root\"></div>` and `<script type=\"module\" src=\"/src/web/main.tsx\"></script>`.\n\n## API (`src/api/index.ts`)\nDefault-export a Hono app (it has a `fetch` handler). Put every API route under `/api/`; everything else is served by the SPA.\n\n```ts\nimport { Hono } from 'hono';\nimport type { Env } from './env';\n\nconst app = new Hono<{ Bindings: Env }>();\napp.get('/api/health', (c) => c.json({ ok: true }));\nexport default app;\n```\n\n## Bindings (`src/api/env.ts`)\nThe platform provides exactly these at runtime; declare them in your `Env` interface:\n- `DB: D1Database` — your app's database.\n- `ASSETS: Fetcher` — the built SPA (injected; don't declare it in `wrangler.jsonc`).\n- `EMAIL` — send email (see the `email` topic; injected, don't declare it in `wrangler.jsonc`).\n- Your string `vars` and your secrets (see the `secrets` topic).\n\n## Runtime rules\n- Workers runtime, not Node: no `fs`, no child processes, no native addons, no listening on ports.\n- Each request may use up to {{APP_CPU_MS_PER_REQUEST}} ms of CPU and {{APP_SUBREQUESTS_PER_REQUEST}} outbound requests.\n- Hash passwords with WebCrypto (PBKDF2) or `bcryptjs`, never native `bcrypt`.\n\n## Rules checked before every build\n\n{{RULES}}\n\n## Packages you must not use\n\n{{DENYLIST}}\n",
  database: "# Database\n\nEvery app has its own **D1** (SQLite) database, available as `env.DB`.\n\n## Schema changes: migrations\n- Put SQL files in `migrations/`, named `NNNN_description.sql` (`0001_init.sql`, `0002_add_todos.sql`, …).\n- Before each deploy, the platform applies every migration that hasn't been applied yet, in filename order.\n- **Never edit or rename a migration after it has been deployed.** Add a new numbered file instead. Editing an applied migration fails the deployment with `MIGRATION_FAILED` and keeps the previous version live.\n- A failing statement also fails the deployment with `MIGRATION_FAILED` (the error names the file). Fix it by writing a corrected **new** migration if the broken one was never applied, or a follow-up migration otherwise.\n- Rollbacks do not revert migrations.\n\n## Querying from code\nUse `env.DB.prepare(sql).bind(...).all()` / `.first()` / `.run()`, or Drizzle:\n\n```ts\nimport { drizzle } from 'drizzle-orm/d1';\nconst db = drizzle(c.env.DB);\n```\n\n## Inspecting and fixing data\n`query_database({ app, sql, params? })` runs one statement against the app's database. It is read-only unless you pass `allow_writes: true` — ask the user before changing data. See the schema with `SELECT name, sql FROM sqlite_master`. Results are capped at {{QUERY_MAX_ROWS}} rows.\n",
  email: "# Email\n\nApps send email through the `EMAIL` binding. Every app has its own sending domain: messages come from `hello@mail.<slug>.{{APPS_DOMAIN}}`, with your app's name (or `from_name`) as the sender name. Set `reply_to` if replies should reach a real inbox.\n\n```ts\ntype AppEmailMessage = {\n  to: string | string[];          // 1..{{MAX_EMAIL_RECIPIENTS}} recipients\n  subject: string;                // 1..200 characters\n  text?: string; html?: string;   // at least one\n  reply_to?: string;\n  from_name?: string;             // default: the app's name\n};\ntype AppEmailResult =\n  | { ok: true; id: string; suppressed: string[] }\n  | { ok: false; error: { code: 'invalid_message' | 'all_suppressed' | 'quota_exceeded'\n                              | 'tenant_not_ready' | 'tenant_paused' | 'send_failed'; message: string } };\n\n// src/api/env.ts\nexport interface Env {\n  EMAIL: { send(message: AppEmailMessage): Promise<AppEmailResult> };\n  // …\n}\n\nconst result = await c.env.EMAIL.send({ to: 'someone@example.com', subject: 'Welcome', text: 'Hi!' });\nif (!result.ok) console.error(result.error);\n```\n\n- `send` never throws; always check `result.ok`.\n- `tenant_not_ready`: email is still being set up — usually for a few minutes after the app is created. Tell the user to try again shortly.\n- Addresses that bounced or complained are skipped and listed in `suppressed`.\n- Each organization can send up to {{MAX_EMAILS_PER_ORG_PER_DAY}} emails per day; messages are limited to {{bytes:MAX_EMAIL_BYTES}}.\n",
  secrets: "# Secrets\n\nUse secrets for API keys and anything else that must not be in the code.\n\n- Set: `set_secret({ app, name, value })` — ask the user for the value; never write it into files.\n- Names are UPPER_SNAKE_CASE (`STRIPE_API_KEY`), not `DB`, `ASSETS`, `EMAIL`, or a name used in `vars`.\n- Read in code as `c.env.STRIPE_API_KEY`; declare it as `string` in your `Env` interface.\n- Changes apply immediately, without a redeploy, and survive later deployments.\n- `list_secrets` shows names only; `delete_secret` removes one.\n- Up to {{MAX_SECRETS_PER_APP}} secrets per app, {{bytes:MAX_SECRET_BYTES}} each.\n",
  limits: "# Limits\n\n| What | Limit |\n|---|---|\n| Apps per account | {{MAX_APPS_PER_ORG}} |\n| Deployments per day | {{MAX_DEPLOYS_PER_ORG_PER_DAY}} |\n| Emails per day | {{MAX_EMAILS_PER_ORG_PER_DAY}} |\n| Files per `write_files` call | {{MAX_FILES_PER_WRITE}} |\n| Bytes per `write_files` call | {{bytes:MAX_WRITE_BYTES}} |\n| Bytes per file | {{bytes:MAX_FILE_BYTES}} |\n| File path length | {{MAX_PATH_LENGTH}} characters |\n| Build artifact | {{bytes:MAX_ARTIFACT_BYTES}} |\n| Worker bundle (compressed) | {{bytes:MAX_WORKER_BUNDLE_BYTES}} |\n| Static asset files | {{MAX_ASSET_FILES}} files, {{bytes:MAX_ASSET_FILE_BYTES}} each |\n| CPU per request | {{APP_CPU_MS_PER_REQUEST}} ms |\n| Outbound requests per request | {{APP_SUBREQUESTS_PER_REQUEST}} |\n| Secrets per app | {{MAX_SECRETS_PER_APP}} ({{bytes:MAX_SECRET_BYTES}} each) |\n| `query_database` result | {{QUERY_MAX_ROWS}} rows / {{bytes:QUERY_MAX_BYTES}} |\n| Recipients per email | {{MAX_EMAIL_RECIPIENTS}} |\n| Tool calls per minute | {{TOOL_CALLS_PER_USER_PER_MINUTE}} |\n\nWhen a limit is reached, tools return `QUOTA_EXCEEDED` or `RATE_LIMITED` with details; tell the user which limit it was.\n",
  troubleshooting: "# Troubleshooting\n\n| Symptom | Fix |\n|---|---|\n| `CONTRACT_VIOLATION` | Fix every item in `error.violations`; each has a rule ID and a `fix`. |\n| `BUILD_FAILED` with TypeScript errors | Open the files/lines in `error.errors`, fix the types, write again. |\n| `Rollup failed to resolve import \"x\"` | Add the package to `package.json` dependencies (or fix the import path). |\n| `npm error ERESOLVE` / `E404` | Fix the version range or the package name in `package.json`. |\n| `MIGRATION_FAILED` | Never edit applied migrations; add a new numbered migration (see `database`). |\n| `/api/...` returns the HTML page | `assets.run_worker_first` must include `\"/api/*\"`, and the route must exist in Hono. |\n| Page refresh on a client route returns 404 | `assets.not_found_handling` must be `\"single-page-application\"`. |\n| `Error: Cannot find module 'fs'` (or other Node built-ins) | The runtime isn't Node; use Web APIs or a Workers-compatible package. |\n| Exceeded CPU limit | Move heavy work out of the request path; avoid large synchronous loops; paginate queries. |\n| Secrets are `undefined` | Set them with `set_secret`; declare them in `Env`; names are case-sensitive. |\n| App shows \"being built\" | No deployment is live yet; check `get_deployment`. |\n",
} as const;
